-- top-decks-gauteng-wapadrand (researched)
UPDATE businesses SET description = 'Top Decks, Gauteng is a carpentry business in Wapadrand, Pretoria, building and installing custom timber decks, patios, pergolas, pool decks and built-in braais, and is a preferred installer for Envirodeck and Rhino Wood composite decking. The company''s range extends beyond decking into wooden flooring, balustrading and handrails, along with jacuzzi and splash pool sales and installation for clients building a fuller outdoor entertainment area.

Tiling, cladding and canvas awning installation round out the business''s outdoor and entertainment-area offering, letting a client cover decking, flooring, pool features and shade in one project rather than coordinating several separate contractors. Operating in both Pretoria and Cape Town gives the company experience building timber structures suited to South Africa''s varied climate, where good timber decking can be enjoyed year-round. Homeowners across Wapadrand and wider Pretoria wanting a timber deck, patio, pergola or built-in braai, or a fuller outdoor entertainment upgrade, can work with this Envirodeck and Rhino Wood-approved installer.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.topdecks.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'top-decks-gauteng-wapadrand' AND description = 'Top Decks, Gauteng is a carpentry business in Wapadrand, Pretoria, building and installing custom timber decks, patios, pergolas, pool decks and built-in braais, and is a preferred installer for Envirodeck and Rhino Wood composite decking.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
